{
  "type": "object",
  "properties": {
    "idioma": {
      "type": "string",
      "enum": [
        "es",
        "pt"
      ],
      "description": "Idioma del cliente y de la conversación: 'pt' si el cliente es de Brasil o habló en portugués; 'es' si habló en español."
    },
    "interlocutores": {
      "type": "string",
      "description": "Nombres de las personas del cliente (ej: Francisco, Yasmín y Máximo)"
    },
    "emails_destinatarios": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Emails de los interlocutores del cliente mencionados en la llamada. Si no se mencionaron explícitamente, devolver array vacío []."
    },
    "saludo_intro": {
      "type": "string",
      "description": "Frase de saludo inicial y agradecimiento por la reunión en el idioma detectado (es o pt)."
    },
    "desafios_puntos": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Viñetas de 1 línea cada una. OBLIGATORIO: resaltar con negrita (*texto*) las métricas (*500–600 facturas mensuales*), canales (*correo, WhatsApp, formato físico y diferentes portales de proveedores*), circuitos (*facturas con Orden de Compra y compras directas*) y momentos de cierre (*picos de trabajo durante el cierre y comienzo de cada mes*)."
    },
    "solucion_encaje": {
      "type": "string",
      "description": "Párrafo breve de 2 o 3 oraciones. OBLIGATORIO: resaltar con negrita (*texto*) los conceptos clave (ej: *lectura, imputación y registración*, *API*, etc.)."
    },
    "proximos_pasos": {
      "type": "string",
      "description": "Párrafo de próximos pasos. OBLIGATORIO: resaltar con negrita (*texto*) el día/hora (*el jueves a la misma hora*), la *demostración de Xtract* y la *propuesta comercial, alcance y tiempos estimados de implementación*."
    },
    "cierre_despedida": {
      "type": "string",
      "description": "Frase corta de cierre (ej: Quedo atento.)."
