// =====================================================================
// MODO PRUEBA -- UNICO LUGAR PARA CAMBIARLO
//
// Con un valor cargado, TODOS los borradores van a este DM y NUNCA al
// comercial real. Para pasar a produccion, dejarlo en '' (string vacio).
//
// Existe porque el 28/08 el borrador de Creta Disegno le llego a Nicolas
// creyendo que estabamos probando: este workflow no tenia interruptor y
// la tabla KNOWN_OWNERS resuelve al comercial siempre. El DM de respaldo
// (SLACK_FALLBACK_DM) NO alcanza: solo actua cuando NO se pudo resolver
// al owner, que casi nunca pasa.
// =====================================================================
const FORZAR_DESTINATARIO = 'D0BRPUE84UA';

const notion = $('Code - Extraer Datos').first().json || {};
const iaRaw = $('IA - Redactar borrador de correo').first().json || {};
const ia = iaRaw.output || iaRaw;

// 1. Resolver Destinatarios (Emails del cliente)
const emailsNotion = Array.isArray(notion.emails) ? notion.emails : (notion.emails ? [notion.emails] : []);
const emailsIa = Array.isArray(ia.emails_destinatarios) ? ia.emails_destinatarios : (ia.emails_destinatarios ? [ia.emails_destinatarios] : []);
const todosEmails = [...new Set([...emailsNotion, ...emailsIa].map(e => String(e || '').trim().toLowerCase()))].filter(e => e && e.includes('@'));
const paraTexto = todosEmails.length ? todosEmails.join(', ') : '*(Completar emails de los interlocutores)*';

// 2. Nombres y Comercial
const interlocutores = (ia.interlocutores || notion.persona || 'equipo').trim();
const rawOwner = (Array.isArray(notion.owner) ? notion.owner[0] : notion.owner) || notion.ownerEmail || '';
const ownerLocal = rawOwner.split('@')[0].replace(/[._-]+/g, ' ');
const nombreComercial = ownerLocal ? ownerLocal.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ') : 'Nicolás';

// 3. Construir Bloques del Correo
const saludo = ia.saludo_intro || ('Hola ' + interlocutores + ', buenas tardes.\nGracias nuevamente por el tiempo de hoy.');

// Bullets de desafíos
const puntos = Array.isArray(ia.desafios_puntos) ? ia.desafios_puntos : (ia.desafios_puntos ? [ia.desafios_puntos] : []);
const bloqueDesafios = puntos.length ? puntos.map(p => '• ' + p.replace(/^[•\-\*]\s*/, '')).join('\n') : (ia.desafio || '');

// Párrafo de solución
const bloqueSolucion = ia.solucion_encaje || ia.solucion || '';

// Documentación de API (si aplica)
let bloqueApi = '';
if (ia.menciono_validacion_tecnica) {
  bloqueApi = '\nLes comparto además la <https://xtractapi.docs.apiary.io/#|documentación de la API Rest de Xtract>, para que el equipo técnico pueda validar la viabilidad del consumo y la integración.';
}

// Próximos pasos
const bloqueProximos = ia.proximos_pasos ? ('\n' + ia.proximos_pasos) : '\nComo acordamos, coordinamos una videollamada la semana próxima para presentarles la propuesta y mostrarles el circuito completo.';

// Casos de Éxito oficiales
const bloqueCasosExito = [
  'Casos de éxito:',
  '• <https://www.youtube.com/watch?v=k2uYl5kSGBQ|MODO x Xtract: la experiencia real de un equipo contable en Fintech>',
  '• <https://www.youtube.com/watch?v=k2uYl5kSGBQ|Pomelo + Xtract: Contabilización Automática de Facturas en SAP con IA>'
].join('\n');

// Cierre y firma
const cierre = (ia.cierre_despedida || 'Quedo atento a su disponibilidad para enviarles la invitación.\n\nSaludos y muchas gracias!') + '\n' + nombreComercial;

// 4. Ensamble del Borrador Completo
const cuerpoEmail = [
  saludo,
  '',
  'Por lo que conversamos, hoy el principal desafío está en:',
  bloqueDesafios,
  '',
  bloqueSolucion,
  bloqueApi,
  bloqueProximos,
  '',
  bloqueCasosExito,
  '',
  cierre
].filter(x => x !== undefined && x !== null).join('\n').replace(/\n{3,}/g, '\n\n');

// 5. Matching en Cascada para encontrar el ID de Slack del Comercial
const norm = s => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const emailNorm = norm(rawOwner);
const local = norm(rawOwner.split('@')[0]);
const comoNombre = local.replace(/[._-]+/g, ' ');

// Tabla estática de resguardo por si users.list tiene rate limit 429
const KNOWN_OWNERS = {
  'nicolas.gonzalez@xtract.app': 'U02MCAHHM1T',
  'wenceslao.hoepner@xtract.app': 'U0BBASA0F60',
  'damian.deggeller@xtract.app': 'U09PYEWUHGF',
  'greta.bruno@xtract.app': 'U096BLX5864',
  'ian.brandan@xtract.app': 'U09FZ5MLF0E'
};

let usuarios = [];
try {
  const raw = $('Slack - Traer usuarios').first().json;
  usuarios = (raw.members || raw.users || []).filter(u => u && u.id && !u.deleted && !u.is_bot);
} catch(e) {}

const perfil = u => u.profile || {};
let owner = usuarios.find(u => norm(perfil(u).email) === emailNorm) || null;
if (!owner) owner = usuarios.find(u => norm(u.name) === local) || null;
if (!owner) owner = usuarios.find(u => norm(perfil(u).display_name) === local) || null;
if (!owner) owner = usuarios.find(u => norm(u.real_name) === comoNombre) || null;
if (!owner) owner = usuarios.find(u => norm(perfil(u).real_name) === comoNombre) || null;

const SLACK_FALLBACK_DM = 'D0BRPUE84UA';
const ownerSlackIdReal = owner ? owner.id : (KNOWN_OWNERS[emailNorm] || SLACK_FALLBACK_DM);
const ownerSlackId = FORZAR_DESTINATARIO || ownerSlackIdReal;
const enModoPrueba = !!FORZAR_DESTINATARIO;
const esFallback = !owner && !KNOWN_OWNERS[emailNorm];

// Link a Notion
const rawId = (notion.id || notion.page_id || '').replace(/-/g, '');
const notionUrl = notion.url || (rawId ? ('https://www.notion.so/' + rawId) : '');
const empresa = notion.property_nombre_oportunidad || notion.empresa || 'Cliente';

// 6. Mensaje Formateado para Slack
const textoSlack = [
  // El cartel va PRIMERO y sin ambiguedad: un borrador de prueba es
  // indistinguible de uno real, y el riesgo es que alguien lo copie y lo
  // mande al cliente.
  (enModoPrueba ? ':test_tube: *MODO PRUEBA* — en produccion esto le hubiera llegado a `' + ownerSlackIdReal + '`' : ''),
  ':incoming_envelope: *Borrador de Email Post-Discovery* — ' + empresa,
  (notionUrl ? '• <' + notionUrl + '|Abrir card en Notion>' : ''),
  (esFallback ? '_Nota: Enviado a fallback de pruebas._' : ''),
  '',
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  '*Para:* ' + paraTexto,
  '*Subject:* Resumen de nuestra reunión + Próximos pasos — Xtract',
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  '',
  cuerpoEmail,
  '',
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  '_Listo para copiar y enviar en Gmail / Outlook._'
].filter(Boolean).join('\n');

return [{ json: {
  texto_slack: textoSlack,
  cuerpo_email: cuerpoEmail,
  para: paraTexto,
  subject: 'Resumen de nuestra reunión + Próximos pasos — Xtract',
  owner_slack_id: ownerSlackId,
  comercial: nombreComercial,
  empresa: empresa,
  notion_url: notionUrl
} }];
